-- Migración: 512 criterios oficiales Resolución 3100/2019
BEGIN;
DELETE FROM questionnaire_criteria;
DELETE FROM evaluation_criteria;

-- TSTH: Talento Humano (25 criterios)
INSERT INTO evaluation_criteria (code, number, name, description, complexity, standard_id, is_mandatory, status)
SELECT c.code, c.number, c.name, c.name, c.complexity,
  (SELECT id FROM evaluation_standards WHERE evaluation_standards.code = 'TSTH' LIMIT 1),
  TRUE, 'active'
FROM (VALUES
  ('TSTH-001', '1', '1. El talento humano en salud y otros profesionales que se relacionan con la atención o resultados en salud de los usuarios, cuentan con los titulos, según aplique, de educación superior o certificados de aptitud ocupacional, expedidos por la entidad educativa competente. En el caso de títulos o certificados obtenidos en el extranjero, copia de la resolución de convalidación expedida por el Ministerio de Educación Nacional', 'medium'),
  ('TSTH-002', '2', '2. El talento humano en salud cuenta con copia de la resolución de autorización del ejercicio expedido por la autoridad competente  o inscripción e en el ReTHUS', 'medium'),
  ('TSTH-003', '3', '3. El prestador de servicios de salud determina la cantidad necesaria de talento humano requerido para cada uno de los servicios ofertados y prestados, de acuerdo con la capacidad instalada, la relación entre la oferta y demanda, la oportunidad en la prestación, tiempo de la atención y el riesgo en la atención. Este criterio no aplica para profesionales independientes de salud', 'medium'),
  ('TSTH-004', '4', '4. El prestador de servicios de salud que actúe como escenario de práctica formativa en el área de la salud, cuenta con:', 'simple'),
  ('TSTH-005', '5', '4.1. Convenio vigente con la institución educativa autorizada por la entidad competente', 'simple'),
  ('TSTH-006', '6', '4.2. Información documentada de los mecanismos de supervisión permanente del personal en entrnamiento', 'simple'),
  ('TSTH-007', '7', '4.3. Estudio de la capacidad instalada en el cual se dtermine el número máximo de estudiantes que simultaneamente puedan acceder por programa de formación y por jornada, para cada uno de los servicios que se utilicen como escenarios de práctica formativa en el área de la salud, estudio que debe ser elaborado teniendo en cuenta los "lineamientos de referencia para la asignación de cupos de estudiantes en escenarios clinicos" publicados por el Ministerio de Salud y Protección Social', 'complex'),
  ('TSTH-008', '8', '5. En los servicios de salud diferentes a los servicios de consulta externa especializada de dolor y cuidado paliativo, donde se atienden pacientes con enfermedades terminales, crónicas, degenerativas e irreversibles, a los cuales se les decida como conducta médica: como parte del plan integral de cuidado que gestiona el equipo de salud, o por solicitud del paciente; el manejo de dolor y cuidado paliativo, el profesional en medicina tratante cuenta con constancia de asistencia en las acciones de formación continua en el manejo de dolor y cuidado paliativo, cuando no sea especialista en dolor y cuidado paliativo', 'complex'),
  ('TSTH-009', '9', '6. El talento humano en salud de los servicios de atención del parto, cuidado intensivo y cuidado intermedio neonatal, pediátrico y adultos, cuentan con constancia de asistencia en las acciones de formación continua para la gestión del duelo', 'complex'),
  ('TSTH-010', '10', '7. En los servicios de salud donde se realicen imagenes diagnósticas por ultrasonido, cuenta con médico especialista en radiologia e imagenes diagnósticas también podrán realizar imagenes diagnósticas aquellos médicos especialistas, quienes en su pensum o formación académica hayan adquirido los conocimientos del manejo e interpretación del espectro electromagnetico, del ultrasonido especialmente, así como de la radiaciones ionizantes para establecer el diagnóstico o el tratamiento de las enfermedades inherentes a su especialidad, para lo cual deberá acreditar el respectivo certificado.', 'medium'),
  ('TSTH-011', '11', '8. Los profesionales de la medicina de los servicios de hospitalización de baja, mediana y alta complejidad, hospitalización paciente crónico con y sin ventilador, cuidados intensivos neonatales, pediátricos y adultos; urgencias, y servicios del grupo quirurgico en modalidad intramural,cuentan con certificación vigente de aprobación de la evaluación de competencias esenciales para el cuidado de la donante expedida por el Instituto Nacional de Salud.', 'medium'),
  ('TSTH-012', '12', '9. Las instituciones prestadoras de servicios de salud con servicios de cuidado intensivo pediatrico y adulto que adicionalmente habiliten servicio quirurgico de neurocirugía, tienen disponibilidad de coordinador operativo de trasplantes.', 'medium'),
  ('TSTH-013', '13', '10. El talento humano en salud de los servicios de salud de los grupos de consulta externa, internación y el servicio de urgencias, cuentan con constancia de asistencia en las acciones de formación continua en la atención integral en salud de las personas victimas de violencia sexual.', 'medium'),
  ('TSTH-014', '14', '11. El talento humano en salud de los servicios de transporte asistencial, atención prehospitalaria y urgencias, cuentasn con constancia de asistencia en las acciones de formación continua en la atención a personas víctimas de ataques con agentes químicos.', 'medium'),
  ('TSTH-015', '15', '12. Cuando en un servicio de salud se realicen "pruebas en punto de atención del paciente - (point of care testing - POCT)", el talento humano en salud qeu las realice, a excepción del profesional en bacteriologia cuenta con constancia de asistencia en las acciones de formación continua en la atención a personas víctimas de ataques con agentes químicos.', 'medium'),
  ('TSTH-016', '16', '13. Procedimientos bajo sedación:', 'simple'),
  ('TSTH-017', '17', '13.1 Cuando fuera de salas de cirugía, se realicen procedimientos bajo sedación Grado I y II, adicional al profesional de salud que realiza el procedimiento, cuenta con:', 'medium'),
  ('TSTH-018', '18', '13.1.1. Profesional en la medicina especialista en anestesiologia, o profesional de la medicina o profesional en odontologia, según aplique, el cual será el encargado de administrar el medicamento y realizar el monitoreo continuo del paciente (registro de signos vitales y la respuesta a la sedación)', 'medium'),
  ('TSTH-019', '19', '13.1.2. Todos los profesionales, a excepción del profesional de la medicina especialista en anestesiologia, deben demostrar constancia de asistencia a curso de formación continua en soporte vital básico y sedación', 'medium'),
  ('TSTH-020', '20', '13.1.3 Para sedacción con óxido nitroso en odontologia, el profesional de la odontología cuenta con constancia de asistencia en las acciones de formación continua para uso clínico y práctico de este gas.', 'medium'),
  ('TSTH-021', '21', '13.2. Cuando fuera de las salas de cirugia, se realicen procedimientos bajo sedación grado III, adicional al profesional de salud que realiza el procedimiento, cuenta con profesional de la medicina con especialidad médico - quirúrgica, quién será el responsable de administrar la sedación', 'medium'),
  ('TSTH-022', '22', '13.3. Cuando fuera de las salas de cirugía, se realicen procedimientos bajo sedación grado IV, adicional al profesional de  salud que realiza el procedimiento, cuenta con profesional de la medicina especialisa en anestesiologia, quién será el responsable de administrar la sedación', 'medium'),
  ('TSTH-023', '23', '13.4 Cuenta con profesional de la medicina especialista en anestesiologia cuando la atención de trate de pacientes con caracteristicas particulares: poco colaboradores; edades extremas; con enfermedades severas:cardíacas, pulmonares, hepáticas, renales o del sistema nervioso central;cualquier alteración del grado de consciencia, con obesidad mórbida, con apnea del sueño, embarazadas, o quienes abusan del alcohol o de las drogas; antecedentes de sedación fallida o que presentaron efectos adversos a algún medicamento utilizado en la sedación, por tener un elevado riesgo de desarrollar complicaciones relacionadas con la sedación analgesia', 'medium'),
  ('TSTH-024', '24', 'Modalidad de telemedicina prestador remisor - prestador de referencia', 'simple'),
  ('TSTH-025', '25', '14. Adicional a los criterios del estándar de talento humano enunciados que le aplique, el talento humano en salud que preste directamente un servicio de salud bajo la modalidad telemedicina cuentan con constancia de asistencia en las acciones de formación continua en el manejo de tecnología utilizada por el prestador, los procesos y herramientas inherentes a la prestación de servicios bajo esta modalidad', 'complex')
) AS c(code, number, name, complexity)
ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.name;

-- TSINF: Infraestructura (197 criterios)
INSERT INTO evaluation_criteria (code, number, name, description, complexity, standard_id, is_mandatory, status)
SELECT c.code, c.number, c.name, c.name, c.complexity,
  (SELECT id FROM evaluation_standards WHERE evaluation_standards.code = 'TSINF' LIMIT 1),
  TRUE, 'active'
FROM (VALUES
  ('TSINF-001', '1', 'Edificaciones de uso exclusivo en salud', 'simple'),
  ('TSINF-002', '2', '1. Los servicios de salud de urgencias, de atención del parto, hospitalarios y de cirugía que realicen procedimientos quirúrgicos no ambulatorios, solo se pueden prestar en edificaciones de uso exclusivo de salud.', 'medium'),
  ('TSINF-003', '3', '2. Los servicios de salud de: urgencias, cirugía y del grupo de internación, así como en los servicios de salud donde se realice el proceso de esterilización, deben contar con ambiente de aseo de uso exclusivo', 'complex'),
  ('TSINF-004', '4', '3. Cuando en una edificación de uso exclusivo de salud funcione más de un prestador de servicios de salud con servicios de los grupos de consulta externa y apoyo diagnóstico y complementación terapeutica, cada prestador cuenta con infraestructura separada delimitada fisicamente. Se pueden compartir los siguientes ambientes y áreas: aseo, salas de espera y unidades sanitarias.', 'medium'),
  ('TSINF-005', '5', '4. Las edificaciones donde se presten servicios de salud de urgencias y del grupo de internación, cuentan con tanque de almacenamientode agua para el consumo humano que garantice como mínimo una reserva de 24 horas de servicio continuo, calculando con base en el consumo de 600 lt por cama/camilla al día.', 'medium'),
  ('TSINF-006', '6', '5. Cuando el prestador de servicios de salud cuente con mas de una infraestructura y estas se puedan vincular funcionalmente entre si, lo harán mediante tunel o puente cubierto, o muro(s) colindante(s) que cuenten con acceso (s) que intercomuniquen las infraestructuras, de uso exclusivo del prestador y adicionalmente cumplen con las siguientes caracteristicas:', 'medium'),
  ('TSINF-007', '7', '5.1. Ancho que permita la movilización de camas, camillas, sillas de ruedas, equipos biomédicos  y personal para el traslado de los pacientes  en condiciones seguras.', 'medium'),
  ('TSINF-008', '8', '5.2. El piso del túnel o puente debe ser uniforme y de material antideslizante o con elementos que garanticen esta propiedad en todo su recorrido, con pasamanos d a ambos lados y con protecciones laterales hacia espacios libres.', 'medium'),
  ('TSINF-009', '9', '5.3. Lo anterior siempre y cuando la norma urbanística de la jurisdicción donde se localizan las sedes hayan aprobado esta forma de vinculación funcional entre las mismas.', 'medium'),
  ('TSINF-010', '10', '5.4. Esta edificación se podrá habilitar como una o varias sedes, de acuerdo con lo que determine el prestador de servicios de salud', 'medium'),
  ('TSINF-011', '11', 'Edificaciones de uso mixto', 'simple'),
  ('TSINF-012', '12', '6. Cuando en una edificación de uso mixto funcione más de un prestador de servicios de salud, cada uno cuenta con infraestructura separada y delimitada físicamente. Se pueden compartir las salas de espera y las unidades sanitarias.', 'medium'),
  ('TSINF-013', '13', '7. En edificaciones de uso mixto pueden funsionar los prestadores de servicios de salud que oferten y presten servicios de los grupos de consulta externa. de apoyo diagnóstico y complementación terapeutica y los servicios del grupo quirurgico que realicen exclusivamente procedimientos de cirugia ambulatoria.', 'medium'),
  ('TSINF-014', '14', 'Edificaciones de uso exclusivo en salud y edificaciones de uso mixto', 'simple'),
  ('TSINF-015', '15', '8. Los prestadores de servicios de salud ubicados en edificaciones de hasta tres (3) pisos o niveles contados a partir del nivel más bajo construido, y que funcione en segundo o tercer nivel o piso, cuentan con ascensor o rampa o sistema alternativo de elevación. El sistema alternativo de elevación no puede ser utilizado cuando se presten servicios hospitalarios, cirugía, urgencias o de atención del parto.', 'medium'),
  ('TSINF-016', '16', '9. Los sistemas alternativos de elevación deben cumplir con las siguientes condiciones:', 'simple'),
  ('TSINF-017', '17', '9.1. Su ubicación no interfiera con el acceso y evacuación de los usuarios por las escaleras', 'simple'),
  ('TSINF-018', '18', '9.2. Estén disponibles tanto para el acceso como para la evacuación de los usuarios', 'simple'),
  ('TSINF-019', '19', '9.3. Su manejo sea autonomo', 'simple'),
  ('TSINF-020', '20', '9.4. Garanticen seguridad durante su uso', 'simple'),
  ('TSINF-021', '21', '10. Las edificaciones con más de tres (3) pisos o niveles, contados a partir del nivel más bajo construido, cuentan con ascensor.', 'medium'),
  ('TSINF-022', '22', '11. En edificaciones donde se presten servicios de los grupos de internación, atención del parto, quirurgicos o urgencias para la movilización de pacientes en camilla, la cabina de los ascensores debe tener las dimensiones interiores mínimas de 2.20 de profundidad y de 1.20 ancho, que garanticen el traslado seguro de los pacientes. Las dimensiones de la cabina podrán ser variables en el o los ascensores que el prestador determine para la movilización de usuarios a pie o en silla de ruedas.', 'medium'),
  ('TSINF-023', '23', '12. Si se tienen escaleras o rampas, el piso debe ser uniforme y de material antideslizante o con elementos que garanticen esta propiedad en todo su recorrido, con pasamanos de preferencia a ambos lados y con protecciones laterales hacia espacios libres.', 'medium'),
  ('TSINF-024', '24', '13. Las edificaciones donde se presten servicios de salud cuentan con suministro de agua, energia eléctrica, conexión a la red de alcantarillado y sistemas de comunicaciones.', 'medium'),
  ('TSINF-025', '25', '14. En edificaciones donde se presten servicios de cirugía, atención del parto, laboratorio clínico, urgencias, gestión pre transfusional, dialisis, hospitalarios, imagénes diagnósticas, vacunación, servicio farmaceutico y los que requieran cadena de frio, cuentan con planta electrica.', 'complex'),
  ('TSINF-026', '26', '15. El prestador de servicios de salud que utilice equipos generadores de radiaciones ionizantes cuenta con licencia de práctica médica vigente expedida por la entidad competente.', 'medium'),
  ('TSINF-027', '27', '16. El prestador de servicios de salud que utilice fuentes radiactivas cuenta con autorización vigente de empleo de material radiactivo, expedida por la entidad reguladora competente', 'medium'),
  ('TSINF-028', '28', '17. Cada prestador de servicios de salud debe contar con el respectivo concepto sanitario que dé cumplimiento a lo establecido en la normatividad sanitaria vigente en aspectos tales como agua para consumo humano, gestión de residuos, control de vectores, orden y aseo, condiciones locativas, entre otros. Este concepto será emitido por las autoridades sanitarias correspondientes, en el marco de sus competencias, y debe considerar los servicios de apoyo como lavanderia y servicio de alimentación.

Cuando estos servicios de apoyo son contratados con terceros dichos proveedores deben contar con el concepto sanitario correspondiente a la actividad de bienes y servicios que presta.', 'complex'),
  ('TSINF-029', '29', 'Generalidades de los ambientes y las áreas de los servicios y sus características', 'simple'),
  ('TSINF-030', '30', '18. Las áreas y ambientes de todos los servicios de salud cuentan con ventilación natural o artificial.', 'simple'),
  ('TSINF-031', '31', '19. Las áreas de circulación están libres de obstáculos de manera que permitan la movilización de pacientes, talento humano, usuarios y equipos biomédicos', 'medium'),
  ('TSINF-032', '32', '20. Los ambientes y áreas que hagan parte de cualquier servicio de salud, deben permitir la instalación y movilización de equipos biomedicos y personal necesarios para la atención del paciente en condiciones de rutina o de emergencia.', 'medium'),
  ('TSINF-033', '33', '21.En los servicios del grupo quirurgico, los ambientes y áreas clasificados como no restringidos, semirestringidos, deben señalizarse mediante la demarcación permanente en piso con material lavable y resistente al tráfico pesado, utilizando los siguientes colores', 'medium'),
  ('TSINF-034', '34', '21.1. Verde: Ambientes o áreas no restringidas', 'simple'),
  ('TSINF-035', '35', '21.2. Amarillo: Ambientes o áreas semi-restringidas', 'simple'),
  ('TSINF-036', '36', '21.3. Roja: Ambientes o áreas restringidas', 'simple'),
  ('TSINF-037', '37', '22. Cada uno de los pisos o niveles de la edificación cuenta con señalización y planos indicativos de las rutas de evacuación, salidas de emergencia y puntos de encuentro, visible al público en general.', 'medium'),
  ('TSINF-038', '38', '23. Si el prestador de servicios de salud no tiene habilitado el servicio de gestión pre-transfusional, pero realiza procedimientos de transfusión sanguínea en alguno de sus servicios habilitados, tiene disponibilidad de un área con iluminación y ventilación natural o artificial, para la ubicación de la dotación requerida de acuerdo con los componentes sanguíneos a transfundir.', 'complex'),
  ('TSINF-039', '39', '24. Cuando un prestador de servicios de salud realice procedimientos bajo sedación fuera de salas de cirugía, tiene disponibilidad de área o ambiente para la recuperación de pacientes que puede ser la misma área o ambiente donde se realiza el procedimiento, garantizando la privacidad del usuario.', 'medium'),
  ('TSINF-040', '40', '25. El prestador de servicios de salud que realice el proceso de esterilización, cuenta con:', 'complex'),
  ('TSINF-041', '41', '25.1. Ambiente o área de recibo de material contaminado.', 'simple'),
  ('TSINF-042', '42', '25.2. Ambiente o área de lavado', 'simple'),
  ('TSINF-043', '43', '25.3. Ambiente o área de secado', 'simple'),
  ('TSINF-044', '44', '25.4. Ambiente o área de empaque.', 'simple'),
  ('TSINF-045', '45', '25.5. Ambiente o área de esterilización', 'simple'),
  ('TSINF-046', '46', '25.6. Ambiente o área para almacenamiento de material esteril', 'simple'),
  ('TSINF-047', '47', '25.7. Mesón de trabajo con poceta', 'simple'),
  ('TSINF-048', '48', '25.8. Lavamanos, cuando el proceso se realice fuera del servicio de salud', 'complex'),
  ('TSINF-049', '49', '26. El prestador de servicios de salud que contrate el proceso de esterilización, dentro de su infraestructura cuenta con:', 'complex'),
  ('TSINF-050', '50', '26.1. Ambiente o área para lavado, limpieza y desinfección y entrega de material limpio al proveedor', 'simple'),
  ('TSINF-051', '51', '26.2.  Ambiente o área para la recepción y almacenamiento del material esteril', 'simple'),
  ('TSINF-052', '52', '27. El prestador de servicios de salud que realice el proceso de esterilización en una cetral de esterilización cuenta con los siguientes ambientes y áreas señalizadas unidireccionales y de circulación restringida.', 'complex'),
  ('TSINF-053', '53', '27.1. Ambiente de recibo y lavado de material contaminado', 'simple'),
  ('TSINF-054', '54', '27.2. Ambiente limpio con las siguientes áreas:', 'simple'),
  ('TSINF-055', '55', '27.2.1. Área de secado', 'simple'),
  ('TSINF-056', '56', '27.2.2. Área de empaque', 'simple'),
  ('TSINF-057', '57', '27.2.3. Área de esterilización', 'simple'),
  ('TSINF-058', '58', '27.3. Ambiente para almacenamiento de material esteril', 'simple'),
  ('TSINF-059', '59', 'Caracteristicas de los ambientes y áreas que pueden ser requeridos en varios servicios de salud', 'simple'),
  ('TSINF-060', '60', '28. Consultorio: para efectos del presente manual se definen los siguientes tipos de consultorios de acuerdo con la oferta de servicios:', 'medium'),
  ('TSINF-061', '61', '28.1. Consultorio donde se realiza examen fisico: ambiente con mínimo 10 mt2 (sin incluir la unidad sanitaria) que cuenta con_', 'medium'),
  ('TSINF-062', '62', '28.1.1. área para entrevista', 'simple'),
  ('TSINF-063', '63', '28.1.2. área de examen', 'simple'),
  ('TSINF-064', '64', '28.1.3. Lavamanos. No se exige adicional si el consultorio cuenta con unidad sanitaria', 'simple'),
  ('TSINF-065', '65', '28.1.4. Las áreas están separadas entre si por barrera física fija o móvil, con excepción de los consultorios del servicio de urgencias, optometría y oftalmologia, donde no se requiere.', 'medium'),
  ('TSINF-066', '66', '28.2. Consultorio donde se realizan procedimientos: ambiente mínimo de 10 m2 (sin incluir la unidad sanitaria) que cuenta con:', 'medium'),
  ('TSINF-067', '67', '28.2.1. Área para entrevista.', 'simple'),
  ('TSINF-068', '68', '28.2.2. Área de procedimientos.', 'simple'),
  ('TSINF-069', '69', '28.2.3. Las áreas están separadas entre sí por barrera física fija.', 'simple'),
  ('TSINF-070', '70', '28.2.4. Mesón de trabajo.', 'simple'),
  ('TSINF-071', '71', '28.2.5. Poceta, cuando la requiera, según los procedimientos que el prestrador documente en el estándar de procesos prioritarios.', 'complex'),
  ('TSINF-072', '72', '28.2.6. Lavamanos. No se exige adiocnal si el consultorio cuenta con una unidad sanitaria.', 'simple'),
  ('TSINF-073', '73', '28.3 Consultorio odontológico con una unidad odontológica: Ambiente con mínimo 10 m2 (sin incluir la unidad sanitaria) cuenta con:', 'medium'),
  ('TSINF-074', '74', '28.3.1. Área para entrevista, si la requiere', 'simple'),
  ('TSINF-075', '75', '28.3.2. Área para unidad odontológica.', 'simple'),
  ('TSINF-076', '76', '28.3.3. Lavamanos. No se exige adicional si el consultorio cuenta con unidad sanitaria.', 'simple'),
  ('TSINF-077', '77', '28.3.4. Área con mesón de trabajo con poceta.', 'simple'),
  ('TSINF-078', '78', '28.4. Consultorio odontológico con más de una unidad odontológica: Ambiente con mínimo 10 m2 (sin incluir la unidad sanitaria) que cuenta con:', 'medium'),
  ('TSINF-079', '79', '28.4.1. Área adicional por cada unidad odontológica que permita la instalación y movilización de talento humano, pacientes, usuarios y equipos biomédicos.', 'medium'),
  ('TSINF-080', '80', '28.4.2. Barrera física fija o móvil entre las unidades odontológicas.', 'simple'),
  ('TSINF-081', '81', '28.4.3. Mínimo un lavamanos por cada tres unidades odontológicas o fracción.', 'simple'),
  ('TSINF-082', '82', '28.4.5. A partir de tres unidades odontológicas, adicional a lo mencionado en los numerales 28.4.1, 28.4.2 y 28.4.3, tiene disponibilidad de un ambiente con mesón de trabajo y poceta.', 'medium'),
  ('TSINF-083', '83', '29. Consultorio donde se realiza únicamente entrevista, no se realiza examen físico ni procedimientos: Ambiente con mínimo 4 m2 (sin incluir la unidad sanitaria), cuenta con:', 'medium'),
  ('TSINF-084', '84', '29.1. Área para entrevista, según el tipo de consulta.', 'simple'),
  ('TSINF-085', '85', '29.2. Lavamanos. No se exige adicional si el consultorio cuenta con unidad sanitaria.', 'simple'),
  ('TSINF-086', '86', '30. Sala de procedimientos: Es el ambiente donde se realizan procedimientos derivados de los servicios de salud. Para efectos del presente manual, se definen los siguientes tipos de sala:', 'medium'),
  ('TSINF-087', '87', '30.1. Sala de procedimientos o curaciones. 
Ambiente con mínimo 8 m2, que cuenta con:', 'simple'),
  ('TSINF-088', '88', '30.1.1. Mesón de trabajo', 'simple'),
  ('TSINF-089', '89', '30.1.2. Poceta, cuando la requiera, según los procedimientos que el prestador documente en el estándar de procedimientos prioritarios.', 'medium'),
  ('TSINF-090', '90', '30.1.3. Lavamanos', 'simple'),
  ('TSINF-091', '91', '30.2. Sala de procedimientos de Litotricia: 
Ambiente con dimensión variable acirde con la tecnólogía utilizada, que cuenta con mesón de trabajo con poceta y disponibilidad de:', 'medium'),
  ('TSINF-092', '92', '30.2.1. Vestidor para pacientes con área para casilleros.', 'simple'),
  ('TSINF-093', '93', '30.2.2. Área de recuperación.', 'simple'),
  ('TSINF-094', '94', '30.2.3. Unidad sanitaria.', 'simple'),
  ('TSINF-095', '95', '30.3. Sala de procedimientos endoscópicos:
Ambiente con dimensión variable acorde con el tipo de tecnología utilizada y los procedimientos que se realicen, cuenta con:', 'medium'),
