  ('TSDOT-041', '41', '16.1. Sistemas de telecomunicaciones de doble vía.', 'simple'),
  ('TSDOT-042', '42', '16.2. Cuando se realicen pruebas para la detección de eventos de interés en salud pública, cuenta con:', 'simple'),
