  ('TSDOT-046', '46', 'Modalidad telemedicina', 'simple'),
  ('TSDOT-047', '47', '17. El prestador de servicios de salud realiza el mantenimiento de la tecnología de información y de comunicaciones para avalar la calidad de la información, y adicionalmente cuenta con:', 'medium'),
  ('TSDOT-048', '48', '17.1. Prestador remisor', 'simple'),
  ('TSDOT-049', '49', '17.1.1. Documento firmado por un ingeniero biomédico con tarjeta profesional vigente, que certifique que:', 'simple'),
