  ('TSDOT-051', '51', '17.1.1.2. Los equipos de captura utilizados por  el prestador de servicios de salud garantizan que la información obtenida es equivalente a la original, de manera que al ser reproducida se garantice su calidad y confiabilidad.', 'medium'),
  ('TSDOT-052', '52', '17.1.1.3. Los parámetros de digitalización y compresión seleccionados en los equipos durante la captura de datos o imágenes garantizan la resolución necesaria para permitir el diagnóstico.', 'medium'),
  ('TSDOT-053', '53', '17.1.1.4. Si el prestador de servicios  de salud realiza consulta dermatológica en la modalidad de telemedicina cuenta con cámara digital de alta resolución que permita un fácil enfoque de las lesiones de piel y revisión de las imágenes capturadas previo a la transmisión al dermatólogo.', 'medium'),
  ('TSDOT-054', '54', '17.1.2. Documento firmado por un ingeniero de sistemas con tarjeta profesional vigente, que certifique que:', 'simple'),
  ('TSDOT-055', '55', '17.1.2.1. Los dispositivos utilizados para transferencia de información sincrónica por videoconferencia garantizan óptima fidelidad y calidad del video y sonido para el prestador remisor y para e! prestador de referencia.', 'medium'),
  ('TSDOT-056', '56', '17.1.2.2. El software utilizado se adapta al cambio en la disponibilidad del ancho de banda sin perder conexión. En el caso que la videoconferencia sea grabada se deberán contemplar todos criterios de seguridad informática, que permita resguardar adecuadamente la confidencialidad y privacidad del paciente.', 'medium'),
  ('TSDOT-057', '57', '17.1.2.3. Las pantallas o monitores grado médico utilizados para el despliegue de imágenes cuentan con una distancia máxima de 0.25 milímetros entre píxeles
(dot pitch), para garantizar la interpretación adecuada de la información recibida.', 'medium'),
  ('TSDOT-058', '58', '17.2. Prestador de referencia.', 'simple'),
  ('TSDOT-059', '59', '17.2.1. Documento firmado por un ingeniero de sistemas con tarjeta profesional vigente, que certifique que:', 'simple'),
  ('TSDOT-060', '60', '17.2.1.1. Los dispositivos utilizados para transferencia de información sincrónica por videoconferencia garantizan una óptima fidelidad y calidad del video y sonido tanto para el prestador remisor como para el prestador de referencia.', 'medium'),
  ('TSDOT-061', '61', '17.2.1.2. El software utilizado se adapta al cambio de la disponibilidad del ancho de banda sin perder la conexión.', 'simple'),
  ('TSDOT-062', '62', '17.2.1.3. En el caso que la videoconferencia sea grabada se deberán contemplar todos los criterios de seguridad informática, que permita resguardar adecuadamente la confidencialidad y privacidad del paciente.', 'medium'),
  ('TSDOT-063', '63', '17.2.2. Las pantallas o monitores grado médico utilizados para el despliegue de imágenes cuentan con una distancia máxima de 0.19 milímetros entre pixeles (dot pitch), resolución mínima de 1024 x 768 pixeles, como mínimo un ratio de contraste de 500:1 y mínimo de luminancia (brillo) de 250 cd/m2 que permita garantizar la interpretación adecuada de la información recibida.', 'medium')
) AS c(code, number, name, complexity)
ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.name;

-- TSMD: Medicamentos, Dispositivos Médicos e Insumos (56 criterios)
INSERT INTO evaluation_criteria (code, number, name, description, complexity, standard_id, is_mandatory, status)
SELECT c.code, c.number, c.name, c.name, c.complexity,
  (SELECT id FROM evaluation_standards WHERE evaluation_standards.code = 'TSMD' LIMIT 1),
  TRUE, 'active'
FROM (VALUES
  ('TSMD-001', '1', '1. El prestador de servicios de salud lleva registros con la información de todos los medicamentos para uso humano requeridos en la prestación de los servicios que oferte; dichos registros cuentan con la siguiente información:', 'medium'),
  ('TSMD-002', '2', '1.1. Principio activo.', 'simple'),
  ('TSMD-003', '3', '1.2. Forma farmacéutica.', 'simple'),
  ('TSMD-004', '4', '1.3. Concentración', 'simple'),
  ('TSMD-005', '5', '1.4. Lote.', 'simple'),
  ('TSMD-006', '6', '1.5. Fecha de vencimiento.', 'simple'),
  ('TSMD-007', '7', '1.6. Presentación comercial.', 'simple'),
  ('TSMD-008', '8', '1.7. Unidad de medida.', 'simple'),
  ('TSMD-009', '9', '1.8. Registro sanitario vigente o permiso cuando se autorice, expedido por el Invima.', 'simple'),
  ('TSMD-010', '10', '2. Los dispositivos médicos de uso humano requeridos para la prestación de los servicios de salud cuentan con información documentada que dé cuenta de la verificación y seguimiento de la siguiente información:', 'medium'),
  ('TSMD-011', '11', '2.1. Descripción.', 'simple'),
  ('TSMD-012', '12', '2.2. Marca del dispositivo.', 'simple'),
  ('TSMD-013', '13', '2.3. Serie (cuando le aplique).', 'simple'),
  ('TSMD-014', '14', '2.4. Presentación comercial.', 'simple'),
  ('TSMD-015', '15', '2.5. Registro sanitario vigente o permiso de comercialización expedido por el Invima.', 'simple'),
  ('TSMD-016', '16', '2.6. Clasificación por riesgo (información consignada en el registro sanitario o permiso de comercialización).', 'simple'),
  ('TSMD-017', '17', '2.7. Vida útil, cuando le aplique.', 'simple'),
  ('TSMD-018', '18', '2.8. Lote', 'simple'),
  ('TSMD-019', '19', '2.9. Fecha de vencimiento', 'simple'),
  ('TSMD-020', '20', '3. Los reactivos de diagnóstico in vitro requeridos para la prestación de los servicios de salud cuentan con la información documentada que dé cuenta de la verificación y seguimiento de la siguiente información:', 'medium'),
  ('TSMD-021', '21', '3.1. Nombre', 'simple'),
  ('TSMD-022', '22', '3.2. Marca', 'simple'),
  ('TSMD-023', '23', '3.3. Presentación comercial', 'simple'),
  ('TSMD-024', '24', '3.4. Registro sanitario vigente o permiso de comecialización expedido por el Invima.', 'simple'),
  ('TSMD-025', '25', '3.5. Clasificación del riesgo santario', 'simple'),
  ('TSMD-026', '26', '3.6. Vida útil, cuando aplique', 'simple'),
  ('TSMD-027', '27', '3.7. Fecha de vencimiento y lote.', 'simple'),
  ('TSMD-028', '28', '4. El prestador de servicios de salud cuenta con información documentada de los procesos generales según aplique, para:', 'complex'),
  ('TSMD-029', '29', '4.1. Selección', 'simple'),
  ('TSMD-030', '30', '4.2. Adquisición', 'simple'),
  ('TSMD-031', '31', '4.3. Transporte', 'simple'),
  ('TSMD-032', '32', '4.4. Recepción', 'simple'),
  ('TSMD-033', '33', '4.5. Almacenamiento', 'simple'),
  ('TSMD-034', '34', '4.6. Conservación', 'simple'),
  ('TSMD-035', '35', '4.7. Control de fechas de vencimiento', 'simple'),
  ('TSMD-036', '36', '4.8. Control de cadena de frío, manejo de contingencias con la cadena de frío', 'simple'),
  ('TSMD-037', '37', '4.9. Distribución', 'simple'),
  ('TSMD-038', '38', '4.10. Dispensación', 'simple'),
  ('TSMD-039', '39', '4.11. Devolución', 'simple'),
  ('TSMD-040', '40', '4.12. Disposición final', 'simple'),
  ('TSMD-041', '41', '4.13. Seguimiento al uso de medicamentos, homeopáticos, fitoterapéuticos, medicamentos biológicos, componentes anatómicos, dispositivos médicos (incluso los sobre medida, elementos de rayos X y de uso odontológico), reactivos de diagnóstico in vitro; así como de los demás insumos asistenciales que se utilicen incluidos los que se encuentran en los depósitos o almacenes del prestador de servicios de salud y en la modalidad extramural.', 'medium'),
  ('TSMD-042', '42', '5. El prestador de servicios de salud que realice algún tipo de actividad con medicamentos de control especial para la prestación de servicios de salud cuenta con la resolución de autorización vigente, expedida por el Fondo Nacional de Estupefacientes o la entidad que haga sus veces.', 'medium'),
  ('TSMD-043', '43', '6. El prestador de servicios de salud cuenta con información documentada de la planeación y ejecución de los programas de farmacovigilancia, tecnovigilancia y reactivovigilancia, que garanticen el seguimiento al uso de medicamentos, dispositivos médicos (incluidos los sobre medida) y reactivos de diagnóstico in vitro, cuando aplique.', 'complex'),
  ('TSMD-044', '44', '7. El prestador de servicios de salud que cuente con reservas de medicamentos, homeopáticos, fititerapéuticos, medicamentos biológicos, componentes anatómicos, dispositivos médicos (incluidos los sobre medida), reactivos de diagnóstico in vitro, y demás insumos asistenciales, debe garantizar que se almacenen en condiciones apropiadas de temperatura, humedad, ventilación segregación y seguridad de acuerdo con las condiciones definidas por el fabricante o el banco del componente anatómico, según aplique, y contar con instrumento para medir humedad reltiva y temperatura y evidencia su registro, control y gestión.', 'complex'),
  ('TSMD-045', '45', '8. Para la aplicación del protocolo de lavado de manos o higienización, los servicios de salud cuentan con los insumos de aseo, limpieza y secado que garanticen su cumplimiento.', 'complex'),
  ('TSMD-046', '46', '9. La suficiencia de dispositivos médicos está relacionada con la frecuencia de uso de los mismos, incluyendo los tiempos del proceso de esterililización, cuando aplique.', 'complex'),
  ('TSMD-047', '47', '10. El prestador de servicios de salud cuenta con paquete para el manejo de derrames y rupturas de medicamentos, ubicado en un lugar de fácil acceso, visible y con adecuada señalización, disponible para su uso en los servicios y ambientes donde se requieran. El prestador de servicios de salud define su contenido de acuerdo con los medicamentos utilizados y lo sugerido por el fabricante en las fichas técnicas.', 'medium'),
  ('TSMD-048', '48', '11. En los servicios donde se requiera carro de paro, adicional a la dotación definida en el presente manual, los medicamentos, dispositivos médicos e insumos deber ser definidos por el prestador de servicios de salud de acuerdo con la morbilidad. riesgos de complicaciones más frecuentes y lo documentado para el procedimiento de reanimación cerebro cardio pulmonar.', 'medium'),
  ('TSMD-049', '49', '12. El prestador debe mantener condiciones de almacenamiento, conservación, control de fechas de vencimiento, uso y custodia de los medicamentos, dispositivos médicos e insumos contenidos en los carros de paro.', 'medium'),
  ('TSMD-050', '50', '13. Si el prestador de servicios de salud no tiene habilitado el servicio de gestión pre transfusional, pero realiza procedimientos de transfusión, cuenta con convenio o contrato vigente con un banco de sangre certificado por la autoridad competente para el suministro de sangre, componentes sanguíneos y la realización de las pruebas pre transfusionales cuando el prestador de servicios de salud no las realice', 'complex'),
  ('TSMD-051', '51', '14. Cuando el prestador de servicios de salud fabrique en su institución gases medicinales, cuenta con la certificación vigente de Buenas Prácticas de Manufactura expedida por el Invima o la entidad que haga sus veces.', 'medium'),
  ('TSMD-052', '52', '15. En los servicios de transporte asistencial, atención prehospitalaria y urgencias cuenta con kit de emergencias para la atención a víctimas de ataques con agentes químicos.', 'medium'),
  ('TSMD-053', '53', '16. Adicional a los criterios enunciados de presente estándar, que le aplique a estas modalidades, el prestador de servicios en salud cuenta con:', 'medium'),
  ('TSMD-054', '54', '16.1. Dispositivos médicos e insumos asistenciales según la patalogía del paciente o eventos de interés en salud pública cuando se requiera.', 'medium'),
  ('TSMD-055', '55', '16.2. Medicamentos de acuerdo con inventario establecido por el prestador acorde a lo documentado en sus procesos prioritarios, cuando se requiera.', 'complex'),
  ('TSMD-056', '56', '17. El prestador de servicio de salud cumple con los criterios que le apliquen del presente estándar.', 'simple')
) AS c(code, number, name, complexity)
ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.name;

-- TSPP: Procesos Prioritarios (109 criterios)
INSERT INTO evaluation_criteria (code, number, name, description, complexity, standard_id, is_mandatory, status)
SELECT c.code, c.number, c.name, c.name, c.complexity,
  (SELECT id FROM evaluation_standards WHERE evaluation_standards.code = 'TSPP' LIMIT 1),
  TRUE, 'active'
FROM (VALUES
  ('TSPP-001', '1', '1. El prestador de servicios de salud cuenta con una política de seguridad del paciente acorde con los lineamientos expedidos por el Ministerio de Salud y Protección Social.', 'complex'),
  ('TSPP-002', '2', '2. El prestador de servicios de salud realiza actividades encaminadas a gestionar la seguridad del paciente.', 'simple'),
  ('TSPP-003', '3', '3. El prestador de servicios de salud cuenta con un comité o instancia que orienta y promueve la política de seguridad del paciente, el control de infecciones y ta optimización del uso de antibióticos, cuando tos prescriba o administre. En el caso de profesionales independientes de salud podrá ser el mismo prestador.', 'complex'),
  ('TSPP-004', '4', '4. El prestador de servicios de salud adopta y realiza las siguientes prácticas seguras, según aplique a su servicio de salud y cuenta con información documentada para:', 'medium'),
  ('TSPP-005', '5', '4.1. Asegurar la correcta identificación del paciente en los procesos asistenciales. (que incluya como mínimo dos identificadores: nombre completo y número de identificación)', 'complex'),
  ('TSPP-006', '6', '4.2. Gestionar y desarrollar una adecuada comunicación entre las personas que atienden y cuidan a los pacientes que incluyan enfoques diferenciales.', 'medium'),
  ('TSPP-007', '7', '4.3. Detectar, prevenir y reducir infecciones asociadas con la atención en salud (que incluya protocolo de higiene de manos o higienización con soluciones a base de alcohol).', 'complex'),
  ('TSPP-008', '8', '4.4. Detectar, ana!izar y gestionar eventos adversos.', 'simple'),
  ('TSPP-009', '9', '4.5. Garantizar la funcionalidad de los procedimientos de consentimiento  informado.', 'simple'),
  ('TSPP-010', '10', '4.6. Mejorar la seguridad en la utilización de medicamentos, en los servicios donde aplique.', 'simple'),
  ('TSPP-011', '11', '4.7. Prevenir y reducir la frecuencia de caídas, en los servicios donde aplique.', 'simple'),
  ('TSPP-012', '12', '4.8. Garantizar la atención segura de ta gestante y el recién nacido, en los servicios donde aplique.', 'simple'),
  ('TSPP-013', '13', '4.9. Prevenir complicaciones asociadas a disponibilidad y manejo de sangre, componentes y a la transfusión sanguínea, en los servicios donde aplique.', 'medium'),
  ('TSPP-014', '14', '4.10. Prevenir úlceras por presión, en los servicios donde aplique.', 'simple'),
  ('TSPP-015', '15', '4.11. Mejorar la seguridad en los procedimientos quirúrgicos, en los servicios donde aplique.', 'simple'),
  ('TSPP-016', '16', '5. El prestador de servicios de salud promueve la cultura de seguridad del paciente que involucra a todo el personal de manera sistemática con un enfoque educativo no punitivo mediante:', 'medium'),
  ('TSPP-017', '17', '5.1. Capacitación del personal en el tema de seguridad del paciente y en los principales riesgos de la atención.', 'simple'),
  ('TSPP-018', '18', '5.2. Actividades donde se ilustra al paciente y sus allegados en el autocuidado de su seguridad.', 'simple'),
  ('TSPP-019', '19', '6. El prestador de servicios de salud cuenta con información documentada de las actividades y procedimientos que se realizan en el servicio acordes con su objeto, alcance y enfoque diferencial, mediante guías de práctica clínica- GPC, procedimientos de atención, protocolos de atención y otros documentos que el prestador de servicios de salud determine, dicha  información  incluye talento humano, equipos biomédicos, medicamentos y dispositivos médicos e insumos requeridos.', 'complex'),
  ('TSPP-020', '20', '7. La información documentada es conocida mediante acciones de formación continua por el talento humano encargado y responsable de su aplicación, incluyendo el talento humano en entrenamiento, y existe evidencia de su socialización.', 'medium'),
  ('TSPP-021', '21', '8. Las guías de práctica clínica y protocolos a adoptar son en primera medida los que disponga el Ministerio de Salud y Protección Social. En caso de no estar disponibles, o si existe nueva evidencia científica que actualice alguna o algunas de las recomendaciones de las guías de práctica clínica o requerimientos de los protocolos, el prestador de servicios de salud adopta, adapta o desarrolla guías de práctica clínica o protocolos basados en evidencia científica, publicados nacional o internacionalmente.', 'complex'),
  ('TSPP-022', '22', '9. El prestador de servicios de salud de acuerdo con las patologías más frecuentes en el servicio define la guía o guías de práctica clínica a adoptar, o adaptar o desarrollar.', 'medium'),
  ('TSPP-023', '23', '10. El prestador de servicios de salud cuenta con información documentada de la adopción, o adaptación o desarrollo de guías práctica clínica o protocolos basados en evidencia científica.', 'complex'),
  ('TSPP-024', '24', '11. Los servicios de salud donde se atiendan pacientes con enfermedades terminales, crónicas, degenerativas e irreversibles, a los cuales se determine el manejo del dolor y cuidado paliativo, cuentan con información documentada para su manejo.', 'medium'),
  ('TSPP-025', '25', '12. El prestador de servicios de salud cuenta con la siguiente información documentada:', 'simple'),
  ('TSPP-026', '26', '12.1. Detección, prevención y disminución del riesgo de accidentes e incidentes de carácter radiológico, en los servicios donde aplique.', 'medium'),
  ('TSPP-027', '27', '12.2. Aseo, limpieza y desinfección de áreas y superficies.', 'simple'),
  ('TSPP-028', '28', '12.3. Procedimiento de reanimación cerebro cardio pulmonar, en los servicios donde se realice.', 'simple'),
  ('TSPP-029', '29', '12.4. Acciones para prevenir las flebitis infecciosas, químicas y mecánicas en los servicios donde se realicen procedimientos de venopunción.', 'medium'),
  ('TSPP-030', '30', '12.5. Aspectos de bioseguridad acordes con las condiciones y características del servicio.', 'simple'),
  ('TSPP-031', '31', '12.6. Descontaminación por derrames de sangre u otros fluidos corporales.', 'simple'),
  ('TSPP-032', '32', '12.7. Manejo de gases medicinales que incluya como mínimo la atención de emergencias y sistema de alarma, cuando se utilicen.', 'complex'),
  ('TSPP-033', '33', '13. El prestador de servicios de salud que realice el proceso de esterilización cuenta con la siguiente información  documentada:', 'complex'),
  ('TSPP-034', '34', '13.1. Buenas prácticas de esterilización de acuerdo con los procedimientos y técnicas que se utilicen, que describa como mínimo los siguientes aspectos:', 'medium'),
  ('TSPP-035', '35', '13.1.1 Recibo de productos contaminados y entrega de material estéril.', 'simple'),
  ('TSPP-036', '36', '13.1.2. Transporte', 'simple'),
  ('TSPP-037', '37', '13.1.3. Lavado, secado y lubricación.', 'simple'),
  ('TSPP-038', '38', '13.1.4. Empaque.', 'simple'),
  ('TSPP-039', '39', '13.1.5. Etiquetado.', 'simple'),
  ('TSPP-040', '40', '13.1.6. Esterilización.', 'simple'),
  ('TSPP-041', '41', '13.1.7. Almacenamiento.', 'simple'),
  ('TSPP-042', '42', '13.1.8. Verificación de la integridad del material estéril', 'simple'),
  ('TSPP-043', '43', '13.1.9. Control de calidad que incluya el análisis de los reportes de dicho control, para la toma de medidas preventivas y correctivas.', 'medium'),
  ('TSPP-044', '44', '14. Cuando un prestador de servicios de salud contrate el proceso de esterilización con un tercero, cuenta con un contrato, convenio o acuerdo escrito entre las partes, el cual debe incluir como mínimo las características de calidad de los productos, la supervisión del estado de las instalaciones y la aplicación de los procedimientos del tercero para realizar el proceso. No obstante, el prestador de servicios de salud que requiere el proceso de esterilización es el responsable de garantizar la esterilidad y el desempeño del producto final.', 'complex'),
  ('TSPP-045', '45', '15. Los prestadores de servicios de salud tienen definidos procedimientos que garanticen el cumplimiento del no reúso de dispositivos médicos cuando el fabricante así lo haya establecido.', 'medium'),
  ('TSPP-046', '46', '16. Hasta tanto el Ministerio de Salud y Protección Social regule la materia, el prestador de servicios de salud podrá reusar dispositivos médicos, siempre y cuando el fabricante de dichos dispositivos autorice su reúso. En tal caso, el prestador de servicios de salud cuenta con información documentada que defina:', 'medium'),
  ('TSPP-047', '47', '16.1. Los procedimientos, siguiendo las recomendaciones del fabricante, para el reprocesamiento y control de calidad que demuestren la eficacia, desempeño y esterilidad del producto.', 'medium'),
  ('TSPP-048', '48', '16.2. Acciones de seguimiento a través de los comités de infecciones, de seguridad del paciente y del programa de tecnovigilancia, que garanticen que el dispositivo no ha perdido la eficacia y desempeño para el cual fue diseñado, ni exponga al riesgo de infecciones o complicaciones al usuario.', 'complex'),
  ('TSPP-049', '49', '16.3. Los profesionales independientes de salud realizarán el seguimiento a través del programa de tecnovigilancia.', 'complex'),
  ('TSPP-050', '50', '17. Para la referencia de pacientes, el prestador de servicios de salud cuenta con la siguiente información documentada:', 'simple'),
  ('TSPP-051', '51', '17.1. Estabilización del paciente antes del traslado.', 'simple'),
  ('TSPP-052', '52', '17.2. Medidas para el traslado.', 'simple'),
  ('TSPP-053', '53', '17.3. Lista de chequeo de los documentos necesarios para el traslado que incluya:', 'simple'),
  ('TSPP-054', '54', '17.3.1. Diligenciamiento del formato de referencia de pacientes.', 'simple'),
  ('TSPP-055', '55', '17.3.2. Resultados de apoyos diagnósticos realizados al paciente.', 'simple'),
  ('TSPP-056', '56', '17.3.3. Resumen de historia clínica.', 'simple'),
  ('TSPP-057', '57', '17.3.4. Mecanismos tecnológicos que le permitan realizar el proceso (software, correo, entre otros).', 'complex'),
  ('TSPP-058', '58', '17.3.5. Talento humano que debe responsabilizarse de cada una de las etapas del proceso.', 'complex'),
  ('TSPP-059', '59', '17.3.6. La referencia de pacientes que se detecten como víctimas de violencia sexual debe hacerse a un servicio de urgencias.', 'medium'),
  ('TSPP-060', '60', '18. Cuando se realicen procedimientos bajo sedación fuera de salas cirugía, el prestador de servicios de salud cuenta con información documentada para:', 'medium'),
  ('TSPP-061', '61', '18.1. Realizar la sedación', 'simple'),
  ('TSPP-062', '62', '18.2. Definición de la atención por médico especialista en anestesiología cuando se identifiquen riesgos para el paciente relacionados con la sedación', 'medium'),
  ('TSPP-063', '63', '18.3. Manejo de emergencias.', 'simple'),
  ('TSPP-064', '64', '18.4. Seguimiento al riesgo, que incluya fichas técnicas de indicadores de complicaciones terapéuticas y medicamentosas, relacionadas con la sedación, medición, seguimiento y planes de mejoramiento.', 'medium'),
  ('TSPP-065', '65', '18.5. Lista de chequeo, consignada en la historia clínica del paciente, que incluya la verificación de:', 'simple'),
  ('TSPP-066', '66', '18.5.1. Evaluación de la vía aérea.', 'simple'),
  ('TSPP-067', '67', '18.5.2. Determinación del tiempo de ayuno.', 'simple'),
  ('TSPP-068', '68', '18.5.3. Registro de monitoreo del nivel de conciencia, la saturación de oxígeno, frecuencia cardíaca, tensión arterial y frecuencia respiratoria.', 'medium'),
  ('TSPP-069', '69', '18.5.4. Registro de las variables hemodinámicas y respiratorias, a intervalos regulares', 'simple'),
  ('TSPP-070', '70', '18.6. Observación bajo la supervisión del profesional que realiza la sedación.', 'simple'),
  ('TSPP-071', '71', '18.7. Todos estos registros se deben realizar antes, durante la intervención y hasta el momento del egreso del paciente.', 'simple'),
  ('TSPP-072', '72', '18.8. Recomendaciones de egreso suministradas al acompañante o acudiente.', 'simple'),
  ('TSPP-073', '73', '19. Si el prestador de servicios de salud no tiene habilitado el servicio de gestión pre transfusional, pero realiza procedimientos de transfusión sanguínea en alguno de sus servicios de salud habilitados, cuenta con la siguiente información documentada:', 'complex'),
  ('TSPP-074', '74', '19.1. Transporte, conservación, embalaje y remisión de muestras al banco de sangre para la realización de pruebas pre transfusionales.', 'medium'),
  ('TSPP-075', '75', '19.2. Manejo, investigación y análisis de las reacciones adversas a las transfusiones sanguíneas y procesos de hemovigilancia.', 'complex'),
  ('TSPP-076', '76', '19.3. Guía de práctica clínica para el uso de componentes sanguíneos.', 'simple'),
  ('TSPP-077', '77', '20. La Institución Prestadora de Servicios de Salud que cuenten con servicios de salud de los grupos de consulta externa, internación o el servicio de urgencias, cuenta con:', 'medium'),
  ('TSPP-078', '78', '20.1. Documento del proceso institucional que orienta la atención en salud de las víctimas de violencias sexuales.', 'complex'),
  ('TSPP-079', '79', '20.2. Documento que dé cuenta la conformación del equipo institucional para la atención integral en salud para las víctimas de violencias sexuales', 'medium'),
  ('TSPP-080', '80', '21. El Profesional Independiente de Salud y las Entidades con Objeto Social Diferente que oferten y presten servicios de salud de los grupos de consulta externa y los prestadores de servicios de salud de Transporte Especial de Pacientes cuentan con documento del proceso que orienta la atención en salud de las víctimas de violencias sexuales.', 'complex'),
  ('TSPP-081', '81', '22. En los servicios de transporte asistencial, atención prehospitalaria y urgencias, se cuenta con documento del proceso que orienta la atención en salud a victimas de ataques con agentes químicos.', 'complex'),
  ('TSPP-082', '82', '23. Los prestadores de servicios de salud cuentan con información documentada de las condiciones de almacenamiento, conservación, control de fechas de vencimiento, uso y custodia de los medicamentos, dispositivos médicos e insumos contenidos en los kits de derrames de medicamentos, ataque con agentes químicos y de violencias sexuales, según su contenido.', 'medium'),
  ('TSPP-083', '83', '24. Las Instituciones Prestadoras de Servicios de  Salud con servicios de hospitalización, hospitalización de paciente crónico con y sin ventilador, cuidado intensivo neonatal, pediátrico y adulto, urgencias y del grupo quirúrgico, en la modalidad intramural, cuentan con la siguiente Información documentada:', 'medium'),
  ('TSPP-084', '84', '24.1. Manejo de la enfermedad cerebro vascular.', 'simple'),
  ('TSPP-085', '85', '24.2. Manejo del Trauma Craneoencefálico.', 'simple'),
  ('TSPP-086', '86', '24.3. Detección de donantes de componentes anatómicos', 'simple'),
  ('TSPP-087', '87', '24.4. Mantenimiento del donante de componentes anatómicos', 'simple'),
  ('TSPP-088', '88', '25. Las Instituciones Prestadoras de Servicios de Salud, con servicios de cuidado intensivo pediátrico y adulto que cuenten con servicios quirúrgicos de neurocirugía de alta complejidad, cuentan con información documentada del procedimiento para el diagnóstico de muerte encefálica y muerte en asistolia.', 'medium'),
  ('TSPP-089', '89', '26. Los servicios de salud que realicen pruebas de interés en salud pública deben inscribirse en el Registro de Laboratorios- RELAB.', 'medium'),
  ('TSPP-090', '90', '27. Cuando el prestador de servicios de salud realice "pruebas en el punto de atención del paciente - (Point of Care Testing - POCT)" en un servicio habilitado cuenta con:', 'medium'),
  ('TSPP-091', '91', '27.1. Información documentada sobre la toma, procesamiento, control de calidad y entrega de resultados.', 'simple'),
  ('TSPP-092', '92', '27.2. Controles de calidad realizados por un servicio de laboratorio clínico que puede ser propio o contratado para tal fin. cuando aplique, de acuerdo a las especificaciones del fabricante.', 'medium'),
  ('TSPP-093', '93', '27.3. Análisis de los reportes del control de calidad y toma de medidas preventivas y correctivas.', 'simple'),
  ('TSPP-094', '94', 'Adicional a los criterios enunciados que le aplique, para las siguientes modalidades el prestador de servicios de salud cuenta con la siguiente información documentada:', 'medium'),
  ('TSPP-095', '95', 'Modalidad extramural jornadas en salud y unidad móvil', 'simple'),
  ('TSPP-096', '96', '28. Orientación a los usuarios sobre las condiciones, requisitos y restricciones de acceso, permanencia y salida del vehículo, en condiciones de rutina o en condiciones de emergencia. a cargo del conductor del vehículo y el talento humano en salud.', 'medium'),
  ('TSPP-097', '97', '29. Mecanismos que garanticen comunicación para el seguimiento de los pacientes que lo requieran.', 'simple'),
  ('TSPP-098', '98', '30. Mecanismos de supervisión de las actividades realizadas en el marco de los eventos de interés en salud pública, cuando aplique.', 'medium'),
  ('TSPP-099', '99', 'Modalidad telemedicina - Prestador Remísor', 'simple'),
  ('TSPP-100', '100', '31. Información documentada de la prestación de servicios en esta modalidad que evidencie:', 'simple'),
  ('TSPP-101', '101', '31.1. La o las categorías de tetemedicina que se ofrece(n) en cada uno de  los servicios habilitados en dicha modalidad y si se presta el servicio como prestador remisor o como prestador de referencia.', 'medium'),
  ('TSPP-102', '102', '31.2. Los flujos de la información', 'simple'),
  ('TSPP-103', '103', '31.3.Los responsables de la atención', 'simple'),
  ('TSPP-104', '104', '31.4. El método de comunicación que se utiliza (sincrónico o asincrónico) para la atención y los criterios para la identificación de los casos en los cuales se debe transferir y recibir la información en tiempo real (sincrónico) o mediante almacenamiento - envio (asincrónico).', 'medium'),
  ('TSPP-105', '105', '31.5. Las caracteristicas y formas de relacionamiento entre prestadores de telemedicina (remisar y de referencia) cuando aplique, definiendo los tiempos de respuesta.', 'medium'),
  ('TSPP-106', '106', '31.6. Procedimiento para la captura, almacenamiento y transmisión de la información.', 'simple'),
  ('TSPP-107', '107', '31.7. Parámetros para la digitalización y compresión durante la captura de datos o imágenes que garanticen la resolución necesaria para permitir el diagnóstico.', 'medium'),
  ('TSPP-108', '108', 'Modalidad telemedicina - Prestador de referencia', 'simple'),
  ('TSPP-109', '109', '32. Adicional a los criterios solicitados para el prestador remisor, cuenta con información documentada de las actividades y procedimientos de los servicios que oferte, acordes con su objeto, alcance y enfoque diferencial, mediante guías de práctica clínica- GPC, procedimientos de atención, protocolos de atención y otros documentos que el prestador de servicios de salud determine, dicha información incluye talento humano, equipos biomédicos, medicamentos y dispositivos médicos e insumos  requeridos.', 'complex')
) AS c(code, number, name, complexity)
ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.name;

-- TSHCR: Historia Clínica y Registros (56 criterios)
INSERT INTO evaluation_criteria (code, number, name, description, complexity, standard_id, is_mandatory, status)
SELECT c.code, c.number, c.name, c.name, c.complexity,
  (SELECT id FROM evaluation_standards WHERE evaluation_standards.code = 'TSHCR' LIMIT 1),
  TRUE, 'active'
FROM (VALUES
  ('TSHCR-001', '1', '1. Toda atención de primera vez a un usuario debe incluir el proceso de apertura de historia clínica. Todos los pacientes atendidos cuentan con historia clínica.', 'complex'),
  ('TSHCR-002', '2', '2. El prestador de servicios de salud cuenta con procedimientos para utilizar una historia única y para el registro de entrada y salida de historias del archivo físico. Ello implica que el prestador de servicios de salud cuente con un mecanismo para unificar la información de cada paciente y su disponibilidad para el equipo de salud.', 'medium'),
  ('TSHCR-003', '3', '3. Los medios electrónicos para la gestión de la historia clínica garantizan la confidencialidad y seguridad, así como el carácter permanente de registrar en ésta y en otros registros asistenciales, sin que se puedan modificar los datos una vez se guarden los registros.', 'complex'),
  ('TSHCR-004', '4', '4. Las historias clínicas cuentan con los componentes y los contenidos mínimos definidos en la normatividad que regula la materia', 'medium'),
  ('TSHCR-005', '5', '5. La historia clínica y los registros asistenciales se diligencian en forma clara, legible, sin tachones, enmendaduras, intercalaciones, sin dejar espacios en blanco y sin utilizar siglas.', 'medium'),
  ('TSHCR-006', '6', '6. Cada anotación lleva la fecha y hora en la que se realiza, con el nombre completo y firma del autor de la misma.', 'simple'),
  ('TSHCR-007', '7', '7. El diligenciamiento de los registros de atención de la historia clínica se realiza simultánea o inmediatamente después de la atención en salud.', 'medium'),
  ('TSHCR-008', '8', '8. La historia clínica y demás registros son conservados en archivo único garantizando la custodia y confidencialidad de los documentos o registros protegidos legalmente por reserva.', 'medium'),
  ('TSHCR-009', '9', '9. El prestador de servicios de salud cuenta con un procedimiento de consentimiento informado que incluye mecanismos para verificar su aplicación, para que el paciente o su responsable, aprueben o no documentalmente, el procedimiento e intervención en salud a que va a ser sometido, previa información de los beneficios, riesgos, alternativas e implicaciones del acto asistencial', 'medium'),
  ('TSHCR-010', '10', '10. Cuando el prestador de servicios de salud utilice mecanismos electrónicos, ópticos o similares para generar, recibir, almacenar, o disponer datos de la historia clínica y para conservarlos, debe avalar que el mecanismo utilizado cumple con características de: autenticidad, fiabilidad, integridad y disponibilidad del documento, de acuerdo con lo establecido en la normatividad vigente expedida por el Archivo General de la Nación, la Superintendencia de Industria y Comercio y el Ministerio de Tecnologías de información y Comunicaciones, para lo cual, el prestador presentará un documento firmado por un ingeniero de sistemas con tarjeta profesional vigente, certificando que el mecanismo usado por el prestador cumple con la normatividad mencionada', 'medium'),
  ('TSHCR-011', '11', 'Cuenta con los siguientes registros, cuando los prestadores de servicios de salud realicen el proceso de esterilización dentro del servicio y fuera de centrales de esterilización:', 'complex'),
  ('TSHCR-012', '12', '11.1. Actividades documentadas y realizadas en el procedimiento de reúso de dispositivos médicos acorde con las recomendaciones del fabricante, incluyendo el número de reúsos por cada dispositivo esterilizado.', 'medium'),
  ('TSHCR-013', '13', '11.2. Registro de cargas.', 'simple'),
  ('TSHCR-014', '14', '11.3. Resultados del control de calidad.', 'simple'),
  ('TSHCR-015', '15', '11.4. Listas del contenido de los paquetes que se esterilizan.', 'simple'),
  ('TSHCR-016', '16', '11.5. Etiquetado de cada paquete que permita la trazabilidad de la esterilización.', 'simple'),
  ('TSHCR-017', '17', '12. Cuando se realicen procedimientos de transfusión de sangre o sus componentes, cuenta con los siguientes registros:', 'simple'),
  ('TSHCR-018', '18', '12.1. Información de los componentes sanguíneos.', 'simple'),
  ('TSHCR-019', '19', '12.2. Solicitud de los componentes sanguíneos.', 'simple'),
  ('TSHCR-020', '20', '12.3. Muestras tomadas para la realización de pruebas pre transfusionales.', 'simple'),
  ('TSHCR-021', '21', '12.4. Muestras remitidas al Banco de Sangre y resultado de las pruebas pre transfusionales con el nombre del Banco de Sangre que las realizó, cuando el prestador no cuente con el servicio de gestión pre transfusional.', 'complex'),
  ('TSHCR-022', '22', '12.5. Información post-transfusional.', 'simple'),
  ('TSHCR-023', '23', '12.6. Informe ante la secretaria departamental o distrital, o la entidad que tenga a cargo dichas competencias, sobre la estadistica mensual de componentes sanguineos trasfundidos.', 'medium'),
  ('TSHCR-024', '24', '12.7. Temperaturas de los equipos biomédicos que lo requieran.', 'simple'),
  ('TSHCR-025', '25', '12.8. Entrega para incineración de bolsas de sangre y de las unidades de sangre o componentes sanguíneos descartados.', 'simple'),
  ('TSHCR-026', '26', '12.9. Transfusiones en la historia clínica del paciente, que incluya como mínimo la razón para la transfusión, el producto y volumen que fue transfundido y la hora de la transfusión.', 'medium'),
  ('TSHCR-027', '27', '13. Las instituciones prestadoras de servicios de salud con servicios en la modalidad intramural para hospitalización, hospitalización paciente crónico con y sin ventilador, cuidados intensivos neonatales, pediatricos y adultos, urgencias y servicios del grupo quirurgico, cuentan con:', 'medium'),
  ('TSHCR-028', '28', '13.1. Registro de donantes detectados', 'simple'),
  ('TSHCR-029', '29', '13.3. Registros en la historia clínica de la información sobre el proceso de donación efectuado por los profesionales de salud inscritos ante el Instituto Nacional de Salud', 'complex'),
  ('TSHCR-030', '30', 'Modalidad Extramural', 'simple'),
  ('TSHCR-031', '31', '14. La historia clínica utilizada en la modalidad extramural es custodiada por el prestador de servicios de salud que oferta y presta el servicio de salud en la modalidad extramural y cuenta con los siguientes registros:', 'medium'),
  ('TSHCR-032', '32', 'Modalidad Extramural Domiciliaria', 'simple'),
  ('TSHCR-033', '33', '14.1. Valoración de ingreso con el respectivo plan de tratamiento', 'complex'),
  ('TSHCR-034', '34', '14.2. Nombre de los pacientes atendidos', 'simple'),
  ('TSHCR-035', '35', '14.3. Registros de referencia y contrarreferencia, cuando se requieran', 'simple'),
  ('TSHCR-036', '36', '14.4. Cuidados por parte del personal de salud', 'simple'),
  ('TSHCR-037', '37', '14.5. Cuidados encargados a la familia cuando aplique', 'simple'),
  ('TSHCR-038', '38', 'Modalidad Extramural Jornada de Salud y Unidad Móvil', 'simple'),
  ('TSHCR-039', '39', '14.6. Registro de rutas, horarios y frecuencias de la prestación de los servicios ofertados', 'simple'),
  ('TSHCR-040', '40', '14.7. Nombre de los pacientes atendidos.', 'simple'),
  ('TSHCR-041', '41', '14.8. Nombre de los pacientes trasladados', 'simple'),
  ('TSHCR-042', '42', '14.9. Fecha y hora de ingreso al servicio', 'simple'),
  ('TSHCR-043', '43', '14.10. Cuidados por parte del personal de salud', 'simple'),
  ('TSHCR-044', '44', '14.11. Cuidados encargados a la familia cuando aplique', 'simple'),
  ('TSHCR-045', '45', '14.12. Registros de las fechas de llegada y de salida, cuando aplique', 'simple'),
  ('TSHCR-046', '46', '14.13. Registros de las actividades realizadas.', 'simple'),
  ('TSHCR-047', '47', 'Modalidad Telemedicina - Prestador remisor  - Prestador de referencia 
Cuenta con:', 'simple'),
  ('TSHCR-048', '48', '15. Documento firmado por un ingeniero de sistemas con tarjeta profesional vigente, que certifique:', 'simple'),
  ('TSHCR-049', '49', '15.1. Los mecanismos que garanticen la custodia, seguridad confidencialidad y conservación integral, durante la transmisión y almacenamiento de la información contenida en la historia clínica y demás registros asistenciales y la reproducibilidad de la información de acuerdo con la legislación vigente', 'medium'),
  ('TSHCR-050', '50', '15.2. Los mecanismos de compresión utilizados por el prestador garantizan que la información recuperada corresponda al dato, imagen o señal original (compresión sin pérdidas).', 'medium'),
  ('TSHCR-051', '51', '15.3. El método utilizado para el uso de la firma electrónica o digital', 'simple'),
  ('TSHCR-052', '52', '15.4. La encriptación de la información para su transmisión y mecanismos de acceso a la misma de acuerdo con lo definido por el prestador de servicios de salud.', 'medium'),
  ('TSHCR-053', '53', '15.5. Los sistemas de seguridad y control de acceso a la aplicación, según tipo de usuario cuando se utilizan sistemas de información compartidos o de acceso remoto', 'medium'),
  ('TSHCR-054', '54', '16. Plan de contingencia en caso de fallas del sistema activo o pérdida de datos', 'complex'),
  ('TSHCR-055', '55', '17. Todos los eventos y transacciones que se realicen con ocasión de la prestación de servicios en la modalidad de telemedicina son documentados y almacenados, y son parte integral de la historia clínica', 'medium'),
  ('TSHCR-056', '56', '18. Registro de las atenciones realizadas en la modalidad de telemedicina', 'simple')
) AS c(code, number, name, complexity)
ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.name;

-- TSINT: Interdependencia de Servicios (6 criterios)
INSERT INTO evaluation_criteria (code, number, name, description, complexity, standard_id, is_mandatory, status)
SELECT c.code, c.number, c.name, c.name, c.complexity,
  (SELECT id FROM evaluation_standards WHERE evaluation_standards.code = 'TSINT' LIMIT 1),
  TRUE, 'active'
FROM (VALUES
  ('TSINT-001', '1', '1. Cuando el servicio interdependiente sea contratado, debe mediar un contrato o un acuerdo escrito entre las dos partes, en el que se establezca que el servicio interdependiente apoya el servicio principal, estableciendo como mínimo:', 'medium'),
  ('TSINT-002', '2', '1.1 Calidad en la entrega de los productos', 'simple'),
  ('TSINT-003', '3', '1.2. Procedimientos documentados de atención en cada servicio independiente', 'simple'),
  ('TSINT-004', '4', '1.3 Tiempos de entrega de los productos', 'simple'),
  ('TSINT-005', '5', '1.4 Supervisión al contratista que garantice la seguridad del resultado del producto contratado.', 'simple'),
  ('TSINT-006', '6', '2. Cuando fuera de salas de cirugía, se realicen procedimientos bajo sedación y monitorización electroencelfalografica con video y radio; el prestador de servicios de salud tendrá disponibilidad del servicio de transporte asistencial', 'medium')
) AS c(code, number, name, complexity)
ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.name;

-- Re-vincular a todos los cuestionarios maestros publicados
INSERT INTO questionnaire_criteria (questionnaire_id, criterion_id)
SELECT q.id, ec.id
FROM questionnaires q CROSS JOIN evaluation_criteria ec
WHERE q.service_id IS NULL AND q.status = 'published'
ON CONFLICT DO NOTHING;

UPDATE questionnaires SET total_criteria = (
  SELECT COUNT(*) FROM questionnaire_criteria WHERE questionnaire_id = questionnaires.id
) WHERE service_id IS NULL;

-- Total: 512 criterios
SELECT COUNT(*) AS total FROM evaluation_criteria;
COMMIT;